"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["47867"],{28498(e){e.exports=JSON.parse('{"id":"FIN-1328","slug":"security-token","term":"Security Token","also_known_as":[],"difficulty":"Advanced","definition":"A security token is a digital token recorded on a blockchain that represents ownership of, or a claim on, a financial asset such as a share, bond or fund unit, and is therefore subject to securities laws.","explanation":["Security tokens aim to combine the features of traditional financial securities with the advantages of blockchain technology, such as faster settlement, easier transfer and the ability to divide assets into smaller units.","Because they represent investments, security tokens must generally comply with securities regulations, including registration or exemption requirements, disclosure rules and restrictions on who can buy them. This distinguishes them from utility tokens, which give access to a product or service, although the line between the two is often debated.","For example, a company might issue bonds as security tokens on a blockchain, with interest payments made automatically to token holders and ownership recorded on the ledger.","In the United States, whether a token is a security is generally assessed using the Howey test, which asks whether people invest money in a common enterprise expecting profits from others\' efforts. Several banks and governments have issued tokenized bonds, but trading markets for security tokens remain small compared with traditional markets."],"note":"","total":1500,"prev":{"slug":"security-interest","term":"Security Interest"},"next":{"slug":"seed-capital","term":"Seed Capital"}}')}}]);